<?php
require_once __DIR__.'/../core/Guard.php';ml_guard_shield(__FILE__);if(PHP_SAPI!=='cli'){ml_guard_deny();}require_once __DIR__.'/../core/Config.php';require_once __DIR__.'/../core/Sync.php';use Core\Sync;$opts=array('task'=>'hourly');$quiet=false;$argv=isset($argv)?$argv:array();$args=array_slice($argv,1);$argError='';$i=0;$nArgs=count($args);while($i<$nArgs){$a=(string)$args[$i];if($a==='--force'){$opts['force']=true;$i++;continue;}if($a==='--quiet'||$a==='-q'){$quiet=true;$i++;continue;}if($a==='--dry'){$opts['dry']=true;$i++;continue;}if($a==='--no-build'){$opts['build']=0;$i++;continue;}if($a==='--build'){$opts['build']=1;$i++;continue;}if($a==='--help'||$a==='-h'){echo"媒资资料库 · 每小时采集\n\n";echo"用法： php cron/sync_hourly.php [选项]\n\n";echo"  --limit=20 或 --limit 20        每个源本次最多入库多少条\n";echo"  --window=day 或 --window day    今日热榜（day|week）\n";echo"  --order=both 或 --order both    hot / popular / both\n";echo"  --sources=tmdb,hongguoduanju     只跑指定源\n";echo"  --interval=55                    与上次同步的最小间隔（分钟）\n";echo"  --max-requests=8                 单次上游请求总数硬闸\n";echo"  --force --no-build --dry --quiet\n";exit(0);}$key='';$val=null;$eq=strpos($a,'=');if(strpos($a,'--')===0&&$eq!==false){$key=substr($a,2,$eq-2);$val=substr($a,$eq+1);$i++;}elseif(strpos($a,'--')===0){$key=substr($a,2);if(!in_array($key,array('limit','window','order','interval','max-requests','sources'),true)){$argError='未知参数：'.$a;break;}if($i+1>=$nArgs||strpos((string)$args[$i+1],'--')===0){$argError='参数缺少值：'.$a;break;}$val=$args[$i+1];$i+=2;}else{$argError='无法识别的参数：'.$a;break;}switch($key){case'limit':$opts['limit']=(int)$val;break;case'window':$opts['window']=(string)$val;break;case'order':$opts['order']=(string)$val;break;case'interval':$opts['interval']=(int)$val;break;case'max-requests':$opts['max_requests']=(int)$val;break;case'sources':$list=array();foreach(explode(',',(string)$val)as $x){$x=trim($x);if($x!==''){$list[]=$x;}}$opts['sources']=$list;break;default:$argError='未知参数：--'.$key;break 2;}}if($argError!==''){fwrite(STDERR,$argError."\n执行 --help 查看用法。\n");exit(1);}if(isset($opts['window'])&&!in_array($opts['window'],array('day','week'),true)){fwrite(STDERR,"--window 只能是 day 或 week。\n");exit(1);}if(isset($opts['order'])&&!in_array($opts['order'],array('hot','popular','both'),true)){fwrite(STDERR,"--order 只能是 hot、popular 或 both。\n");exit(1);}if(isset($opts['limit'])&&($opts['limit']<1||$opts['limit']>200)){fwrite(STDERR,"--limit 范围必须是 1~200。\n");exit(1);}if(isset($opts['interval'])&&($opts['interval']<0||$opts['interval']>1440)){fwrite(STDERR,"--interval 范围必须是 0~1440。\n");exit(1);}if(isset($opts['max_requests'])&&($opts['max_requests']<1||$opts['max_requests']>60)){fwrite(STDERR,"--max-requests 范围必须是 1~60。\n");exit(1);}$cfg=Core\Config::get('sync',array());$enabled=(isset($cfg['hourly_enabled'])&&$cfg['hourly_enabled']!==''&&$cfg['hourly_enabled']!=='0'&&$cfg['hourly_enabled']!==0)?1:0;if(!isset($cfg['hourly_enabled'])||$cfg['hourly_enabled']===''||$cfg['hourly_enabled']==='1'||$cfg['hourly_enabled']===1){$enabled=1;}if(!$enabled){$msg='每小时自动采集已关闭（后台 →「同步采集」→「每小时自动采集」开关）。本次跳过。';if($quiet){echo'SKIP  note='.$msg."\n";}else{echo $msg."\n";}exit(0);}if(!isset($opts['limit'])){$hl=isset($cfg['hourly_limit'])?(int)$cfg['hourly_limit']:3;$hl=max(1,min(50,$hl));$opts['limit']=$hl;}$r=Sync::run($opts);if($quiet){echo sprintf("%s  inserted=%d skipped=%d fetched=%d requests=%d built=%d ms=%d%s\n",$r['ok']?'OK':'FAIL',(int)$r['inserted'],(int)$r['skipped_dup'],(int)$r['fetched'],(int)$r['requests'],(int)$r['built'],(int)$r['ms'],$r['reason']!==''?('  note='.$r['reason']):'');exit($r['ok']?0:1);}echo"==== 媒资资料库 · 采集开始 ".date('Y-m-d H:i:s')." ====\n";echo sprintf("参数：每源上限 %d 条 · 时间窗 %s · 口径 %s · 最低投票 %d · 重复处理 %s\n",(int)$r['params']['limit'],$r['params']['window'],$r['params']['order'],(int)$r['params']['min_votes'],$r['params']['dedupe']);echo"说明：按各源官方限制限流（TMDB 0.3s/请求、、红果短剧需配置），只取最热与最多人看的榜。\n\n";if(!empty($r['skipped'])){echo"[跳过] ".$r['reason']."\n";echo"本次未采集。（要立刻跑请加 --force）\n";exit(0);}foreach($r['sources']as $s){echo"── ".(isset($s['label'])?$s['label']:$s['source'])."\n";if($s['endpoints']){foreach($s['endpoints']as $ep){echo sprintf("   · %-26s 抓到 %d 条%s\n",$ep['path'],(int)$ep['count'],$ep['error']!==''?('   ✗ '.$ep['error']):'');}}echo sprintf("   新增 %d · 重复跳过 %d · 低于票数门槛 %d · 请求 %d 次\n",(int)$s['inserted'],(int)$s['skipped_dup'],(int)$s['skipped_low'],(int)$s['requests']);if(isset($s['msg'])&&$s['msg']!==''){echo"   ⚠ ".$s['msg']."\n";}echo"\n";}echo sprintf("汇总：抓到 %d 条 → 新增 %d 条，重复跳过 %d 条，低于票数门槛 %d 条；上游请求 %d 次，静态页 %d 个，耗时 %.1fs\n",(int)$r['fetched'],(int)$r['inserted'],(int)$r['skipped_dup'],(int)$r['skipped_low'],(int)$r['requests'],(int)$r['built'],$r['ms']/1000);if($r['reason']!==''){echo"提示：".$r['reason']."\n";}if(!$r['ok']){echo"结果：失败（详见上面的提示）\n";}echo"==== 采集结束 ".date('Y-m-d H:i:s')." ====\n";exit($r['ok']?0:1);